if(msw_is_post()){msw_verify_post();$name=trim((string)($_POST['username']??''));$pass=(string)($_POST['password']??'');$hash=msw_client_ip_hash();$key=strtolower($name);$lock=msw_one('SELECT * FROM login_attempts WHERE ip_hash=? AND username_key=?','ss',[$hash,$key]);
 if($lock && !empty($lock['locked_until']) && strtotime((string)$lock['locked_until'])>time())$error='Login temporarily locked. Try again later.';else{$u=msw_one('SELECT * FROM users WHERE username=?','s',[$name]);if($u && (int)($u['is_bot']??0)===0 && password_verify($pass,(string)$u['password_hash'])){msw_stmt('DELETE FROM login_attempts WHERE ip_hash=? AND username_key=?','ss',[$hash,$key]);session_regenerate_id(true);$_SESSION['uid']=(int)$u['id'];msw_initialize_player((int)$u['id']);msw_console_event_for_user((int)$u['id'],'AUTH','LOGIN','Commander authenticated successfully.',[], 'login.php');msw_redirect('dashboard.php');}else{$error='Invalid commander credentials.';$now=date('Y-m-d H:i:s');if(!$lock)msw_stmt('INSERT INTO login_attempts(ip_hash,username_key,attempts,window_started) VALUES(?,?,1,?)','sss',[$hash,$key,$now]);else{if(strtotime((string)$lock['window_started'])<time()-900)msw_stmt('UPDATE login_attempts SET attempts=1,window_started=NOW(),locked_until=NULL WHERE ip_hash=? AND username_key=?','ss',[$hash,$key]);else msw_stmt("UPDATE login_attempts SET attempts=attempts+1,locked_until=IF(attempts+1>=7,DATE_ADD(NOW(),INTERVAL 15 MINUTE),locked_until) WHERE ip_hash=? AND username_key=?",'ss',[$hash,$key]);}}}}
